const { chromium } = require('playwright');
const base='http://127.0.0.1:8787';
const assert=(value,message)=>{if(!value)throw new Error(message);};
async function api(request,method,path,data){const response=await request.fetch(base+path,{method,headers:data===undefined?undefined:{'Content-Type':'application/json'},data});const payload=await response.json().catch(()=>({}));if(response.status()<200||response.status()>=300)throw new Error(`${method} ${path}: ${response.status()} ${payload.message||''}`);return payload;}
(async()=>{const browser=await chromium.launch({headless:true});const context=await browser.newContext({viewport:{width:1440,height:900}});try{const username='editor_binding',password='Editor-Binding-2026!';const signup=await context.request.post(base+'/api/auth/signup',{data:{username,displayName:'Editor Binding',email:'editor-binding@example.test',password,rememberMe:false}});assert(signup.status()===201,'Signup failed.');const onboarding=await api(context.request,'GET','/api/onboarding');const relationships=onboarding.relationshipOptions||onboarding.relationships||onboarding.options?.relationships||[];const intentions=onboarding.intentionOptions||onboarding.intentions||onboarding.options?.intentions||[];await api(context.request,'POST','/api/onboarding/relationship',{relationshipId:relationships[0].id});await api(context.request,'POST','/api/onboarding/intentions',{intentionIds:intentions.slice(0,2).map(item=>item.id)});await api(context.request,'POST','/api/bootstrap/owner',{password});const page=await context.newPage();const errors=[];page.on('pageerror',error=>errors.push(error.message));await page.goto(base+'/dashboard',{waitUntil:'networkidle'});await page.locator('#customize-dashboard').click();await page.locator('#dashboard-editor-toolbar').waitFor({state:'visible'});await page.locator('#dashboard-advanced-tools').waitFor({state:'visible'});assert(await page.locator('#dashboard-multi-select').count()===1,'Advanced controls missing.');assert(await page.locator('#customize-dashboard').isHidden(),'Customize button did not enter editor mode.');assert(errors.length===0,`Page errors: ${errors.join(' | ')}`);await page.locator('#dashboard-cancel-layout').click();await page.locator('#customize-dashboard').waitFor({state:'visible'});console.log('DASHBOARD EDITOR BINDING=PASS');}finally{await context.close();await browser.close();}})().catch(error=>{console.error(`DASHBOARD EDITOR BINDING=FAIL ${error.stack||error}`);process.exit(1);});
